        <tr><td class="bold">ST001</td><td>Highway</td><td class="num">443</td><td class="num">54.25</td><td class="num">54.51</td><td class="num">4.52</td></tr>
        <tr><td class="bold">ST013</td><td>Highway</td><td class="num">459</td><td class="num">53.41</td><td class="num">53.60</td><td class="num">4.69</td></tr>
